#include <iostream>
using namespace std;

int main() {
    int total = 0;
    int cats = 0;
    cin >> total >> cats;

    cout << "每只猫分到 " << total / cats << " 条喵" << endl;
    cout << "还剩 " << total % cats << " 条喵" << endl;
    return 0;
}
